def name_operands(region,address,operation):
 if region!='Station' or address!=0x6DD4:return operation
 for value,name in ((0x983F,'SignatureInput.Entry.FirstWord'),(0x9841,'SignatureInput.Entry.SecondWord'),(0x98A0,'DecodedPanelState.Unknown98A0')):operation=operation.replace('(#'+format(value,'04X')+')','(@'+name+')')
 operation=operation.replace('LD DE, #4B37','LD DE, @DecodedPanelConst.SystemFirst').replace('LD DE, #4E25','LD DE, @DecodedPanelConst.SystemSecond').replace('CP #FE','CP @DecodedPanelConst.FinalCode')
 operation=operation.replace('LD HL, #6E11','LD HL, @FinalExitCopy.Source').replace('LD DE, #4000','LD DE, @FinalExitCopy.Destination').replace('LD BC, #0200','LD BC, @FinalExitCopy.Bytes').replace('JP #4000','JP @StationFinalExit.LoadFinal.Entry')
 return operation
